#!/usr/bin/env bash
# Question 4: Leftovers in ${Q4_NS}-svc. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/audit
mkdir -p /opt/course/audit
chown -R ubuntu:ubuntu /opt/course
kubectl delete namespace "${Q4_NS}-svc" --ignore-not-found --wait=true >/dev/null
kubectl create namespace "${Q4_NS}-svc" >/dev/null 2>&1 || kubectl get namespace "${Q4_NS}-svc" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q4_NS}-svc' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
apps=($(shuf -e cart catalog payments search reviews -n 3))
sas=($(shuf -e ci-deployer cart-runtime metrics-reader legacy-sync backup-agent -n 5))
# The Pods run as the first two ServiceAccounts, and as default; the other three are unused. Two Services select nothing.
for sa in "${sas[@]}"; do kubectl -n "${Q4_NS}-svc" create serviceaccount "$sa" >/dev/null; done
kubectl apply -f - <<EOF >/dev/null
apiVersion: apps/v1
kind: Deployment
metadata: { name: ${apps[0]}, namespace: ${Q4_NS}-svc }
spec:
  replicas: 1
  selector: { matchLabels: { app: ${apps[0]} } }
  template:
    metadata: { labels: { app: ${apps[0]}, tier: backend } }
    spec:
      serviceAccountName: ${sas[0]}
      terminationGracePeriodSeconds: 1
      containers:
        - name: app
          image: busybox:1.36
          command: ["sleep", "infinity"]
---
apiVersion: apps/v1
kind: Deployment
metadata: { name: ${apps[1]}, namespace: ${Q4_NS}-svc }
spec:
  replicas: 1
  selector: { matchLabels: { app: ${apps[1]} } }
  template:
    metadata: { labels: { app: ${apps[1]} } }
    spec:
      serviceAccountName: ${sas[1]}
      terminationGracePeriodSeconds: 1
      containers:
        - name: app
          image: busybox:1.36
          command: ["sleep", "infinity"]
---
apiVersion: apps/v1
kind: Deployment
metadata: { name: ${apps[2]}, namespace: ${Q4_NS}-svc }
spec:
  replicas: 1
  selector: { matchLabels: { app: ${apps[2]} } }
  template:
    metadata: { labels: { app: ${apps[2]} } }
    spec:
      terminationGracePeriodSeconds: 1
      containers:
        - name: app
          image: busybox:1.36
          command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Service
metadata: { name: ${apps[0]}, namespace: ${Q4_NS}-svc }
spec: { selector: { app: ${apps[0]} }, ports: [{ port: 80 }] }
---
apiVersion: v1
kind: Service
metadata: { name: ${apps[1]}, namespace: ${Q4_NS}-svc }
spec: { selector: { app: ${apps[1]} }, ports: [{ port: 80 }] }
---
apiVersion: v1
kind: Service
metadata: { name: backends, namespace: ${Q4_NS}-svc }
spec: { selector: { tier: backend }, ports: [{ port: 80 }] }
---
apiVersion: v1
kind: Service
metadata: { name: ${apps[2]}-v1, namespace: ${Q4_NS}-svc }
spec: { selector: { app: ${apps[2]}, version: v1 }, ports: [{ port: 80 }] }
---
apiVersion: v1
kind: Service
metadata: { name: legacy-gateway, namespace: ${Q4_NS}-svc }
spec: { selector: { app: legacy-gateway }, ports: [{ port: 80 }] }
---
apiVersion: v1
kind: Service
metadata: { name: partner-api, namespace: ${Q4_NS}-svc }
spec: { type: ExternalName, externalName: api.partner.example }
EOF
kubectl -n "${Q4_NS}-svc" wait --for=condition=Available deployment --all --timeout=180s >/dev/null
: "${Q4_NS}"
